const jobs = $input.first().json.data || [];

return jobs.map(job => {
  const cleanDesc = (job.description || '').replace(/<[^>]*>?/gm, ' ').replace(/\s+/g, ' ').trim().slice(0, 6000);
  return {
    json: {
      source: 'arbeitnow',
      id: job.slug,
      title: job.title,
      company: job.company_name,
      url: job.url,
      location_raw: (job.locations || []).join(', '),
      work_policy: job.remote ? 'remote' : 'onsite',
      posted_date: new Date(job.created_at * 1000).toISOString(), // Convert timestamp
      description_text: cleanDesc,
      visa_sponsorship: job.visa_sponsorship === true
    }
  };
});

const items = $input.all();

// Hard veto: drop legal disclaimer, missing fields, string "undefined", and whitespace/empty descriptions
const jobs = items.filter(item => {
  const j = item.json;
  if (!j || !j.position || !j.company) return false;

  // Guard 1: reject literal string "undefined" and whitespace-only IDs
  const id = String(j.id || '').trim();
  if (!id || id.toLowerCase() === 'undefined') return false;

  // Guard 2: reject whitespace-only or HTML-comment-only descriptions (before regex cleaning)
  const desc = String(j.description || '').trim();
  if (desc.length < 50) return false;

  return true;
});

return jobs.map(job => {
  const cleanDesc = (job.description || '').replace(/<[^>]*>?/gm, ' ').replace(/\s+/g, ' ').trim().slice(0, 6000);
  let finalUrl = job.url;
  if (finalUrl && !finalUrl.startsWith('http')) finalUrl = 'https://remoteok.com' + finalUrl;

  return {
    json: {
      source: 'remoteok',
      id: String(job.id).trim(),
      title: job.position,
      company: job.company,
      url: finalUrl,
      location_raw: job.location || 'Worldwide',
      work_policy: 'remote',
      posted_date: job.date,
      description_text: cleanDesc,
      visa_sponsorship: false,
      heuristic_score: 0
    }
  };
}).filter(item => item.json.description_text.length > 100);

const jobs = $input.first().json.jobs || [];
const htmlRegex = /<[^>]*>?/gm; // Regex to strip HTML tags

return jobs.map(job => {
  const cleanDesc = (job.description || '').replace(htmlRegex, ' ').replace(/\s+/g, ' ').trim().slice(0, 6000);
  return {
    json: {
      source: 'remotive',
      id: String(job.id),
      title: job.title,
      company: job.company_name,
      url: job.url,
      location_raw: job.candidate_required_location || 'Worldwide',
      work_policy: 'remote', 
      posted_date: job.publication_date,
      description_text: cleanDesc,
      visa_sponsorship: false 
    }
  };
});

const CFG = $('Load Config').first().json.config;
const seenUrls = new Set($input.all().map(i => i.json.url).filter(Boolean));
const cutoff = Date.now() - CFG.window_days * 86400000;
let seniorRe, juniorRe;
try { seniorRe = new RegExp(CFG.title_senior, 'i'); } catch (e) { seniorRe = /$^/; }
try { juniorRe = new RegExp(CFG.title_junior, 'i'); } catch (e) { juniorRe = /$^/; }
return $('Merge').all().filter(item => {
  const j = item.json || {};
  if (!j.url || !j.source) return false;
  if (seenUrls.has(j.url)) return false;
  const posted = new Date(j.posted_date).getTime();
  if (!posted || posted < cutoff) return false;
  if (CFG.require_remote && j.work_policy !== 'remote') return false;
  if (CFG.arbeitnow_visa_only && j.source === 'arbeitnow' && !j.visa_sponsorship) return false;
  if (seniorRe.test(j.title || '') && !juniorRe.test(j.title || '')) return false;
  const desc = (j.description_text || '').toLowerCase();
  return !CFG.banned_phrases.some(p => desc.includes(p));
});

const CFG = $('Load Config').first().json.config;
const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const scored = $input.all().map(job => {
  const desc = (job.json.description_text || '').toLowerCase();
  let score = 0;
  for (const skill of CFG.skills) { const m = desc.match(new RegExp(esc(skill), 'g')); if (m) score += m.length; }
  return { ...job, json: { ...job.json, heuristic_score: score } };
});
scored.sort((a, b) => b.json.heuristic_score - a.json.heuristic_score);
return scored.slice(0, CFG.slice_cap);

const PROFILE = {
  seniority: 'entry/junior (fresh graduate, 6-month production internship)',
  target_roles: ['Automation Engineer','Integration Engineer','GTM Engineer','RevOps Engineer','Technical Business Analyst','Backend Engineer (integrations)'],
  skills: ['Python','FastAPI','SQL','PostgreSQL','Supabase','REST API design','webhooks','n8n','Apify','LLM/RAG pipelines','BPMN','requirements engineering','Git','Docker'],
  languages: { english: 'professional', arabic: 'native', french: 'reading only' },
  constraints: { work_policy: 'remote only', visa: 'needs sponsorship or contractor-friendly', regions: ['Europe','Gulf','remote-anywhere'] }
};

const SYSTEM = 'You are a strict job-fit analyst. Evaluate ONE job description against ONE candidate profile. Return ONLY valid JSON with exactly this schema: {"match_score": number 0-100, "why_match": string, "red_flags": [string], "confidence": number 0-100, "extracted": {"seniority": string, "work_policy": "remote|hybrid|onsite|unknown", "location_constraint": string, "languages_required": [string], "visa_mention": boolean, "visa_confidence": number 0-100, "contract_friendly": boolean, "company_size_hint": string, "salary": string}}';

return $input.all().filter(job => {
  const desc = (job.json.description_text || '').trim();
  // If description is less than 50 chars, it's garbage. Drop it before LLM burn.
  return desc.length >= 50; 
}).map(job => ({
   // ... existing prompt building code ....map(job => ({
  json: {
    system: SYSTEM,
    prompt: `Candidate profile: ${JSON.stringify(PROFILE)}\n\nJob title: ${job.json.title}\nCompany: ${job.json.company}\nLocation: ${job.json.location_raw}\nDescription: ${(job.json.description_text || '').slice(0, 3500)}\n\nEvaluate fit and extract attributes. JSON only.`,
    job: job.json
  }
}));

// LLM Router v6 — groq-gptoss (proven) → gemini-2.5-flash → gemini-3.5-flash-lite. Cerebras parked (402).
const GROQ_URL = 'https://api.groq.com/openai/v1/chat/completions';
const GEMINI_URL = 'https://generativelanguage.googleapis.com/v1beta/openai/chat/completions';

const CHAIN = [
  { name: 'groq-gptoss',     url: GROQ_URL,   key: () => $env.GROQ_API_KEY,  model: 'openai/gpt-oss-120b' },
  { name: 'gemini-3.5-lite', url: GEMINI_URL, key: () => $env.GEMINI_API_KEY, model: 'gemini-3.5-flash-lite', temperature: 0.2 },
  { name: 'gemini-2.5-flash', url: GEMINI_URL, key: () => $env.GEMINI_API_KEY, model: 'gemini-2.5-flash', temperature: 0.2 }
];

const sleep = ms => new Promise(r => setTimeout(r, ms));
function parseJSON(s) {
  try { return JSON.parse(s); } catch (e) {
    const m = (s || '').match(/\{[\s\S]*\}/);
    try { return m ? JSON.parse(m[0]) : null; } catch (e2) { return null; }
  }
}
const callProvider = async (p, system, prompt) => {
  const body = { model: p.model, messages: [{ role: 'system', content: system }, { role: 'user', content: prompt }] };
  if (typeof p.temperature === 'number') body.temperature = p.temperature;
  const data = await this.helpers.httpRequest({
    method: 'POST', url: p.url,
    headers: { 'Authorization': 'Bearer ' + p.key(), 'Content-Type': 'application/json' },
    body, json: true
  });
  if (data.error) throw new Error(data.error.message || JSON.stringify(data.error));
  const parsed = parseJSON(data.choices?.[0]?.message?.content || '');
  if (!parsed) throw new Error('Unparseable JSON');
  return parsed;
};
const is429 = e => /429|rate|resource has been exhausted/i.test(String(e.message || e));

const items = $input.all();
const results = [];
for (let i = 0; i < items.length; i++) {
  const { system, prompt, job } = items[i].json;
  let llm = null, provider = 'none';
  const errors = {};
  for (const p of CHAIN) {
    for (let attempt = 0; attempt < 2; attempt++) {
      try { llm = await callProvider(p, system, prompt); provider = p.name; break; }
      catch (e) {
        errors[p.name] = String(e.message || e).slice(0, 200);
        if (is429(e) && attempt === 0) { await sleep(25000); continue; }
        break;
      }
    }
    if (llm) break;
  }
  results.push({ json: { job, provider, llm, errors } });
  if (i < items.length - 1) await sleep(8000);
}
return results;

const CFG = $('Load Config').first().json.config;
const W = Object.assign({ match: 0.40, filterFit: 0.25, feasibility: 0.20, recency: 0.15 }, CFG.weights);
const parseDate = v => (typeof v === 'number' && v < 1e12) ? new Date(v * 1000) : new Date(v);
const out = [];
for (const item of $input.all()) {
  const { job, provider, llm } = item.json;
  if (!llm) continue;
  const ex = llm.extracted || {};
  const seniority = (ex.seniority || 'unknown').toLowerCase();
  const workPolicy = (ex.work_policy || 'unknown').toLowerCase();
  const loc = (ex.location_constraint || '').toLowerCase();
  const langs = (ex.languages_required || []).map(l => l.toLowerCase());
  const visa = !!ex.visa_mention, visaConf = Number(ex.visa_confidence || 0), contract = !!ex.contract_friendly;

  if (CFG.strict && !CFG.seniority_ok.includes(seniority)) continue;
  if (workPolicy !== 'remote' && workPolicy !== 'unknown') continue;
  if (langs.some(l => CFG.lang_block.some(b => l.includes(b)))) continue;
  if (CFG.loc_black.some(b => loc.includes(b)) && !CFG.loc_wide.some(k => loc.includes(k))) continue;

  const match = Math.max(0, Math.min(100, Number(llm.match_score) || 0));
  const wide = CFG.loc_wide.some(k => loc.includes(k));
  const filterFit = ((CFG.junior_bonus.includes(seniority) ? 1 : 0) + (workPolicy === 'remote' ? 1 : 0) + (wide ? 1 : 0) + (visa || contract ? 1 : 0)) / 4 * 100;
  const feasibility = visa ? visaConf : (contract ? 65 : (wide ? 55 : 25));
  const days = (Date.now() - parseDate(job.posted_date).getTime()) / 86400000;
  const recency = days <= 2 ? 100 : days <= 7 ? 80 : days <= 14 ? 60 : 40;
  const final = Math.round(W.match * match + W.filterFit * filterFit + W.feasibility * feasibility + W.recency * recency);
  if (final < CFG.min_score) continue;

  out.push({ json: {
    run_date: new Date().toISOString(), source: job.source, title: job.title, company: job.company,
    url: job.url, location_raw: job.location_raw, work_policy: job.work_policy, posted_date: job.posted_date,
    final_score: final, priority: final >= CFG.priority_score, why_match: llm.why_match || '',
    red_flags: (llm.red_flags || []).join('; '), seniority, languages_required: langs.join(', '),
    visa_mention: visa, visa_confidence: visaConf, contract_friendly: contract,
    company_size_hint: ex.company_size_hint || 'unknown', salary: ex.salary || 'not listed',
    confidence: Number(llm.confidence || 0), provider, status: 'new'
  }});
}
if (out.length === 0) return [{ json: { __empty: true } }];
return out;

return $('LLM Router').all()
  .filter(i => i.json.provider !== 'none' && i.json.job && i.json.job.url)
  .map(i => ({ json: { url: i.json.job.url } }));

const router = $('LLM Router').all().map(i => i.json);
const providers = router.map(r => r.provider);
const failures = providers.filter(p => p === 'none').length;

// Router error messages persisted to the sheet (diagnosis without opening the node)
const errors_sample = router
  .filter(r => r.errors && Object.keys(r.errors).length)
  .slice(0, 3)
  .map(r => JSON.stringify(r.errors).slice(0, 200))
  .join(' | ');

// Source-level failure markers from try/catch wrappers
const source_errors = $('Merge').all().filter(i => i.json.__error).length;

const validMatches = $input.all().filter(i => i.json.url); // drops __empty sentinel

return [{ json: {
  run_at: new Date().toISOString(),
  merged: $('Merge').all().length,
  survivors: $('Batch Slice').all().length,
  llm_calls: providers.length - failures,
  providers: providers.join(','),
  failures,
  matches_written: validMatches.length,
  source_errors,
  errors_sample,
  config_rev: $('Load Config').first().json.config.rev
}}];

return $input.all().map(item => {
  const r = item.json;
  return { json: {
    source: 'weworkremotely',
    id: r.guid || r.link,
    title: r.title,
    company: (r.creator || '').trim() || 'unknown',
    url: r.link,
    location_raw: 'Worldwide',
    work_policy: 'remote',
    posted_date: r.isoDate || r.pubDate || new Date().toISOString(),
    description_text: (r.content || r.contentSnippet || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 6000),
    visa_sponsorship: false,
    heuristic_score: 0
  }};
});

const WEBHOOK = $env.DISCORD_WEBHOOK_URL;
if (!WEBHOOK) throw new Error('DISCORD_WEBHOOK_URL missing from n8n environment variables');

const MAXE = Math.min(10, Number($('Load Config').first().json.config.max_embeds || 10)); // Discord hard cap 10
const stats = $('Run Stats').first().json;
const matches = $('Gate & Score').all()
  .map(i => i.json).filter(j => j.url)              // drop __empty sentinel
  .sort((a, b) => b.final_score - a.final_score);

const trunc = (s, n) => { s = s || ''; return s.length > n ? s.slice(0, n - 1) + '…' : s; };

let payload;
if (matches.length === 0) {
  payload = { username: 'Job Radar', embeds: [{
    title: '📡 Daily scan — no new matches',
    color: 8421504,                                  // grey heartbeat
    description: `Merged **${stats.merged}** → survivors **${stats.survivors}** → LLM **${stats.llm_calls}** (${stats.providers}) → matches **0** · failures ${stats.failures} · source errors ${stats.source_errors || 0}`,
    footer: { text: 'run ' + stats.run_at }
  }]};
} else {
  const top = matches.slice(0, MAXE);
  payload = { username: 'Job Radar', embeds: top.map(m => ({
    title: trunc(m.title, 80) + ' — ' + trunc(m.company, 40),
    url: m.url,
    color: m.final_score >= 80 ? 65280 : 16763904,   // green priority / yellow match
    fields: [
      { name: 'Score', value: m.final_score + (m.priority ? ' ⭐' : ''), inline: true },
      { name: 'Location', value: trunc(m.location_raw, 50), inline: true },
      { name: 'Visa/contract', value: ((m.visa_mention ? 'visa ' + m.visa_confidence + '% ' : '') + (m.contract_friendly ? 'contract-ok' : '')) || 'none', inline: true },
      { name: 'Why', value: trunc(m.why_match, 200) },
      { name: 'Red flags', value: trunc(m.red_flags, 120) || 'none' }
    ],
    footer: { text: `${m.source} · ${m.provider} · conf ${m.confidence}` }
  }))};
  if (matches.length > MAXE) payload.embeds[payload.embeds.length - 1].footer = { text: `+${matches.length - MAXE} more in the sheet` };
}

const res = await this.helpers.httpRequest({ method: 'POST', url: WEBHOOK, body: payload, json: true, returnFullResponse: true });
if (!(res.statusCode >= 200 && res.statusCode < 300)) throw new Error('Discord HTTP ' + res.statusCode);
return [{ json: { discord: 'sent', embeds: payload.embeds.length, matches: matches.length } }];

const SOURCE = 'n8n-community';
return $input.all().map(item => {
  const r = item.json;
  const title = (r.title || '').trim();
if (/\[for hire\]|available for hire|available for projects|open for projects|looking for clients/i.test(title)) return null; // freelancer pitches, not jobs
  const text = (title + ' ' + (r.content || '')).toLowerCase();
  return { json: {
    source: SOURCE, id: r.guid || r.link, title, company: 'unknown', url: r.link,
    location_raw: 'Worldwide',
    work_policy: /remote|anywhere|worldwide|emea|europe|utc/i.test(text) ? 'remote' : 'unknown',
    posted_date: r.isoDate || r.pubDate || new Date().toISOString(),
    description_text: (r.content || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 6000),
    visa_sponsorship: false, heuristic_score: 0
  }};
}).filter(Boolean);

const jobs = $input.first().json.jobs || [];
return jobs.map(j => ({ json: {
  source: 'jobicy', id: String(j.id), title: j.jobTitle, company: j.companyName || 'unknown',
  url: j.url, location_raw: j.jobGeo || 'Worldwide', work_policy: 'remote',
  posted_date: j.pubDate || new Date().toISOString(),
  description_text: (j.jobDescription || j.jobExcerpt || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 6000),
  visa_sponsorship: false, heuristic_score: 0
}})).filter(x => !/^(americas|north america|usa|us|canada|apac|asia|australia|latam|latin america)$/i.test(x.json.location_raw));

return $input.all().map(item => {
  const r = item.json;
  return { json: {
    source: 'weworkremotely-mkt',
    id: r.guid || r.link,
    title: r.title,
    company: (r.creator || '').trim() || 'unknown',
    url: r.link,
    location_raw: 'Worldwide',
    work_policy: 'remote',
    posted_date: r.isoDate || r.pubDate || new Date().toISOString(),
    description_text: (r.content || r.contentSnippet || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 6000),
    visa_sponsorship: false,
    heuristic_score: 0
  }};
});

// Monthly thread; each top-level comment = one job post. Empty at month start = safe [].
const SOURCE = 'hn-whoishiring';
try {
  const label = new Date().toLocaleString('en-US', { month: 'long', year: 'numeric' });
  const search = await this.helpers.httpRequest({ method: 'GET', json: true,
    url: 'https://hn.algolia.com/api/v1/search?tags=story&query=' + encodeURIComponent('Ask HN: Who is hiring? ' + label) });
  const hits = search.hits || [];
  const story = hits.find(h => (h.title || '').includes(label)) || hits[0]; // prefer exact-month thread
  if (!story) return [];
  const thread = await this.helpers.httpRequest({ method: 'GET', json: true,
    url: 'https://hn.algolia.com/api/v1/items/' + story.objectID });
  return (thread.children || []).filter(c => c.text).slice(0, 40).map(c => {
    const clean = c.text.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
    const href = (c.text.match(/href="([^"]+)"/) || [])[1];
    return { json: {
      source: SOURCE, id: String(c.id), title: clean.slice(0, 120), company: 'unknown',
      url: href || ('https://news.ycombinator.com/item?id=' + c.id),
      location_raw: 'Worldwide',
      work_policy: /remote|anywhere|worldwide/i.test(clean) ? 'remote' : 'unknown',
      posted_date: c.created_at || story.created_at || new Date().toISOString(),
      description_text: clean.slice(0, 6000), visa_sponsorship: false, heuristic_score: 0
    }};
  });
} catch (e) {
  // Never kill the run: marker item (no url) is dropped by Dedupe but counted in ops
  return [{ json: { source: SOURCE, id: 'error', title: '', company: '', url: '',
    location_raw: '', work_policy: 'unknown', posted_date: new Date().toISOString(),
    description_text: '', visa_sponsorship: false, heuristic_score: 0,
    __error: SOURCE + ': ' + String(e.message || e) } }];
}

// Himalayas — free public JSON API, no key. Queries come from the config tab.
const SOURCE = 'himalayas';
let QUERIES = [];
try {
  const cfgQ = $('Load Config').first().json.config.himalayas_queries;
  QUERIES = Array.isArray(cfgQ) ? cfgQ.map(q => (typeof q === 'string' ? q : q.q)).filter(Boolean) : [];
} catch (e) { QUERIES = []; }
if (!QUERIES.length) QUERIES = ['automation engineer', 'integration engineer', 'revenue operations'];

const seenGuids = new Set();
const out = [];
try {
  for (const q of QUERIES) {
    const res = await this.helpers.httpRequest({ method: 'GET', json: true,
      url: 'https://himalayas.app/jobs/api/search?q=' + encodeURIComponent(q) + '&sort=recent&page=1' });
    for (const j of (res.jobs || [])) {
      if (seenGuids.has(j.guid)) continue;
      seenGuids.add(j.guid);
      const loc = (j.locationRestrictions || []).map(l => l.name).join(', ');
      const posted = j.pubDate ? (j.pubDate > 1e12 ? new Date(j.pubDate) : new Date(j.pubDate * 1000)) : new Date();
      out.push({ json: {
        source: SOURCE, id: j.guid, title: j.title, company: j.companyName || 'unknown',
        url: j.applicationLink || ('https://himalayas.app/jobs/' + (j.companySlug || '')),
        location_raw: loc || 'Worldwide',
        work_policy: 'remote',
        posted_date: posted.toISOString(),
        description_text: (j.description || j.excerpt || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 6000),
        visa_sponsorship: false, heuristic_score: 0
      }});
    }
  }
  return out;
} catch (e) {
  return out.length ? out : [{ json: { source: SOURCE, id: 'error', title: '', company: '', url: '',
    location_raw: (j.location || []).filter(Boolean).join(', ') || 'Worldwide', work_policy: 'unknown', posted_date: new Date().toISOString(),
    description_text: '', visa_sponsorship: false, heuristic_score: 0,
    __error: SOURCE + ': ' + String(e.message || e) } }];
}

const DEFAULTS = {
  rev: 'v0', window_days: 7, slice_cap: 25, min_score: 65, priority_score: 80, max_embeds: 10,
  require_remote: true, arbeitnow_visa_only: true, strict: true,
  weights: { match: 0.40, filterFit: 0.25, feasibility: 0.20, recency: 0.15 },
  seniority_ok: ['entry','junior','mid','mid-level','entry/junior','junior/mid','unknown'],
  junior_bonus: ['entry','junior','entry/junior','junior/mid'],
  lang_block: ['german','french','dutch','spanish','italian','polish'],
  loc_black: ['united states','us only','canada','australia','latin america','brazil'],
  loc_wide: ['worldwide','anywhere','europe','emea'],
  banned_phrases: ['german required','french required','fluent german','fluent french','deutschkenntnisse'],
  skills: ['python','fastapi','n8n','api','integration','automation','javascript','gtm','revops','ba','business analyst','clay','hubspot','salesforce','zapier','enrichment','workflow'],
  title_senior: '\\b(senior|sr\\.?|staff|principal|lead|head of|director|vp|vice president|chief|manager)\\b',
  title_junior: '\\b(junior|jr\\.?|entry|graduate|grad|intern|apprentice|trainee)\\b',
  himalayas_queries: [{ q: 'automation engineer' }, { q: 'integration engineer' }, { q: 'revenue operations' }, { q: 'python engineer', seniority: 'Entry-level' }, { q: 'automation engineer', seniority: 'Entry-level' }],
  revops_enabled: true,
  revops_categories: ['gtm-engineering','core-revops','crm-admin','sales-ops'],
  remocate_enabled: true,
  remocate_categories: ['sales','marketing','analytics','manager']
};
const raw = {};
for (const r of $('Fetch Config').all().map(i => i.json)) if (r.key) raw[String(r.key).trim()] = r.value;
const warnings = [];
const num  = (k, fb) => { const v = raw[k]; if (v === undefined || v === '') return fb; const n = Number(v); if (!Number.isFinite(n)) { warnings.push(k + ':not-number→default'); return fb; } return n; };
const bool = (k, fb) => { const v = raw[k]; if (v === undefined || v === '') return fb; const s = String(v).toLowerCase(); if (s === 'true') return true; if (s === 'false') return false; warnings.push(k + ':not-bool→default'); return fb; };
const list = (k, fb) => { const v = raw[k]; if (v === undefined || v === '') return fb; try { const a = JSON.parse(v); if (!Array.isArray(a)) throw 0; return a; } catch (e) { warnings.push(k + ':bad-json→default'); return fb; } };
const obj  = (k, fb) => { const v = raw[k]; if (v === undefined || v === '') return fb; try { const o = JSON.parse(v); if (!o || Array.isArray(o)) throw 0; return o; } catch (e) { warnings.push(k + ':bad-json→default'); return fb; } };
const str  = (k, fb) => { const v = raw[k]; if (v === undefined || v === '') return fb; return String(v); };
const low  = a => a.map(s => String(s).toLowerCase());

const config = {
  rev: str('rev', DEFAULTS.rev),
  window_days: num('window_days', DEFAULTS.window_days), slice_cap: num('slice_cap', DEFAULTS.slice_cap),
  min_score: num('min_score', DEFAULTS.min_score), priority_score: num('priority_score', DEFAULTS.priority_score),
  max_embeds: num('max_embeds', DEFAULTS.max_embeds),
  require_remote: bool('require_remote', DEFAULTS.require_remote),
  arbeitnow_visa_only: bool('arbeitnow_visa_only', DEFAULTS.arbeitnow_visa_only),
  strict: bool('strict', DEFAULTS.strict),
  weights: obj('weights', DEFAULTS.weights),
  seniority_ok: low(list('seniority_ok', DEFAULTS.seniority_ok)), junior_bonus: low(list('junior_bonus', DEFAULTS.junior_bonus)),
  lang_block: low(list('lang_block', DEFAULTS.lang_block)), loc_black: low(list('loc_black', DEFAULTS.loc_black)),
  loc_wide: low(list('loc_wide', DEFAULTS.loc_wide)), banned_phrases: low(list('banned_phrases', DEFAULTS.banned_phrases)),
  skills: low(list('skills', DEFAULTS.skills)),
  title_senior: str('title_senior', DEFAULTS.title_senior), title_junior: str('title_junior', DEFAULTS.title_junior),
  himalayas_queries: list('himalayas_queries', DEFAULTS.himalayas_queries),
  revops_enabled: bool('revops_enabled', DEFAULTS.revops_enabled),
  revops_categories: list('revops_categories', DEFAULTS.revops_categories),
  remocate_enabled: bool('remocate_enabled', DEFAULTS.remocate_enabled),
  remocate_categories: list('remocate_categories', DEFAULTS.remocate_categories)
};
return [{ json: { config, warnings } }];

const CFG = $('Load Config').first().json.config;
if (CFG.revops_enabled === false) return [];                // config kill-switch
const cutoff = Date.now() - CFG.window_days * 86400000;
const cats = new Set(CFG.revops_categories || []);
// Structured deterministic vetoes — free, pre-slice, from the API's own classified fields
const SENIORITY_VETO = ['senior', 'manager', 'vp', 'director', 'c-level'];
const FLAG_VETO = ['quota-carrying', 'commission-based'];
const MAX_EXP_MIN = 4;                                      // 4+ yrs required ≠ entry/junior profile
const seenIds = new Set();
const out = [];
for (const item of $input.all()) {
  for (const j of ((item.json && item.json.hits) || [])) {
    if (!j || !j.id || !j.title || seenIds.has(j.id)) continue;
    seenIds.add(j.id);
    if (j.is_sponsored) continue;                            // paid placement, not organic
    const posted = Number(j.posted_at) || 0;
    const postedMs = posted > 1e12 ? posted : posted * 1000; // epoch seconds vs ms quirk
    if (!postedMs || postedMs < cutoff) continue;            // window filter, client-side
    if (j.work_mode !== 'remote') continue;
    if (cats.size && !cats.has(j.category)) continue;        // ICP categories only
    if (SENIORITY_VETO.includes(String(j.seniority || '').toLowerCase())) continue;
    if ((Number(j.experience_years_min) || 0) >= MAX_EXP_MIN) continue;
    if ((j.red_flags || []).some(f => FLAG_VETO.includes(String(f).toLowerCase()))) continue;
    const salary = (j.salary_min || j.salary_max)
      ? (j.salary_min || '?') + '–' + (j.salary_max || '?') + ' ' + (j.salary_currency || '')
      : 'not listed';
    out.push({ json: {
      source: 'revopsroles',
      id: String(j.id),
      title: j.title,
      company: j.company_name || 'unknown',
      url: j.source_url || ('https://revopsroles.com/jobs/' + j.id),
      location_raw: j.location_raw || 'Worldwide',
      work_policy: 'remote',
      posted_date: new Date(postedMs).toISOString(),
      description_text: [
        'Title: ' + j.title,
        'Company: ' + (j.company_name || 'unknown') + ' (size: ' + (j.company_size || 'unknown') + ', industry: ' + (j.industry || 'unknown') + ')',
        'Category: ' + j.category + ' | Seniority: ' + j.seniority + ' | Experience: ' + (j.experience_years_min || 0) + '-' + (j.experience_years_max || 'n/a') + ' years',
        'Work mode: ' + j.work_mode + ' | Employment type: ' + (j.employment_type || 'unknown') + ' | Location: ' + (j.location_raw || 'unknown'),
        'Tools: ' + ((j.tools || []).join(', ') || 'not listed'),
        'Salary: ' + salary + ' | Comp structure: ' + (j.comp_structure || 'unknown'),
        'Red flags: ' + ((j.red_flags || []).join(', ') || 'none'),
        'Visa sponsorship: ' + (j.visa_sponsorship === true ? 'yes' : j.visa_sponsorship === false ? 'no' : 'unknown'),
        'Uses AI tools: ' + (j.uses_ai_tools === true ? 'yes' : 'unknown')
      ].join('\n').slice(0, 6000),
      visa_sponsorship: j.visa_sponsorship === true,
      heuristic_score: 0
    }});
  }
}
return out;

// Clay Community (Tightknit SPA) via Jina Reader rendered-markdown bridge — ADR-JR-15
const SOURCE = 'clay-community';
const rawIn = $input.first().json;
const md = typeof rawIn.data === 'string' ? rawIn.data : (typeof rawIn.content === 'string' ? rawIn.content : (typeof rawIn.text === 'string' ? rawIn.text : ''));
const errItem = msg => [{ json: { source: SOURCE, id: 'error', title: '', company: '', url: '',
  location_raw: '', work_policy: 'unknown', posted_date: new Date().toISOString(),
  description_text: '', visa_sponsorship: false, heuristic_score: 0, __error: SOURCE + ': ' + msg } }];
if (md.length < 500) return errItem('empty/unsupported reader payload (' + md.length + ' chars)');

const linkRe = /\[([^\]\n]{8,140})\]\((https:\/\/community\.clay\.com\/x\/share-jobs\/[^)\s]+)\)/g;
const seen = new Set(); const posts = []; let m;
while ((m = linkRe.exec(md)) !== null) {
  if (seen.has(m[2])) continue;
  seen.add(m[2]);
  posts.push({ title: m[1].trim(), url: m[2], start: m.index });
}
if (!posts.length) return errItem('no post links parsed — page format changed?');

const now = Date.now();
const ago = chunk => {
  const t = chunk.match(/(\d+)\s*(minute|min|hour|hr|day|week|month)s?\s*ago/i);
  if (!t) return new Date(now).toISOString();
  const n = Number(t[1]); const u = t[2].toLowerCase();
  const mult = u.startsWith('min') ? 60000 : u.startsWith('h') ? 3600000 : u.startsWith('d') ? 86400000 : u.startsWith('w') ? 604800000 : 2592000000;
  return new Date(now - n * mult).toISOString();
};

const out = [];
for (let i = 0; i < posts.length && out.length < 30; i++) {
  const p = posts[i];
  const end = i + 1 < posts.length ? posts[i + 1].start : md.length;
  const chunk = md.slice(p.start, end);
  const body = chunk.replace(/\[([^\]]*)\]\([^)]*\)/g, '$1').replace(/<[^>]*>/g, ' ')
    .replace(/[#>*_`|]+/g, ' ').replace(/\s+/g, ' ').trim();
  const title = p.title.replace(/<[^>]*>/g, '').trim();
  if (/looking for work|hire me|available for hire|open to work|seeking (a )?(new )?role|my services/i.test(title + ' ' + body.slice(0, 300))) continue; // freelancer pitches, not jobs
  out.push({ json: {
    source: SOURCE, id: p.url, title, company: 'unknown', url: p.url,
    location_raw: 'Worldwide',
    work_policy: /remote|worldwide|anywhere|emea|europe/i.test(body) ? 'remote' : 'unknown',
    posted_date: ago(chunk),
    description_text: (title + '. ' + body).slice(0, 6000),
    visa_sponsorship: false, heuristic_score: 0
  }});
}
return out.length ? out : errItem('links found but all vetoed/empty');

// Remocate (Source #12) — Jina Reader bridge over category pages. ADR-JR-16.
// Fetches 4 category pages, parses inline JDs using date anchors. 4 requests/run.
const CFG = $('Load Config').first().json.config;
if (CFG.remocate_enabled === false) return [];

const CATS = CFG.remocate_categories || ['sales', 'marketing', 'analytics', 'manager'];
const cutoff = Date.now() - CFG.window_days * 86400000;
const sleep = ms => new Promise(r => setTimeout(r, ms));

const errItem = msg => [{ json: { 
  source: 'remocate', id: 'error', title: '', company: '', url: '',
  location_raw: '', work_policy: 'unknown', posted_date: new Date().toISOString(),
  description_text: '', visa_sponsorship: false, heuristic_score: 0, 
  __error: 'remocate: ' + msg 
}}];

const clean = s => (s || '').replace(/\[([^\]]*)\]\([^)]*\)/g, '$1').replace(/<[^>]*>/g, ' ')
  .replace(/[#>*_`|]+/g, ' ').replace(/\s+/g, ' ').trim();

const out = []; 
const seenUrls = new Set();
let fetchFails = 0, marksFound = 0;

for (const cat of CATS) {
  let md = '';
  try {
    const res = await this.helpers.httpRequest({ 
      method: 'GET', json: true,
      url: 'https://r.jina.ai/https://www.remocate.app/job-categories/' + cat 
    });
    md = typeof res.content === 'string' ? res.content : (typeof res.data === 'string' ? res.data : '');
  } catch (e) { fetchFails++; continue; }

  if (md.length < 500) { fetchFails++; continue; }

  // Find date anchors (MM/DD/YYYY) which mark the end of a job's meta-line
  const dateRe = /(\d{1,2})\/(\d{1,2})\/(\d{4})/g; 
  let m; 
  const marks = [];
  while ((m = dateRe.exec(md)) !== null) {
    marks.push({ mm: +m[1], dd: +m[2], yy: +m[3], idx: m.index, end: m.index + m[0].length });
  }
  marksFound += marks.length;

  for (let i = 0; i < marks.length && out.length < 40; i++) {
    const lineStart = md.lastIndexOf('\n', marks[i].idx) + 1;
    const metaLine = md.slice(lineStart, marks[i].end);
    const nextStart = i + 1 < marks.length ? md.lastIndexOf('\n', marks[i + 1].idx) + 1 : md.length;
    const body = md.slice(marks[i].end, nextStart);

    const posted = Date.UTC(marks[i].yy, marks[i].mm - 1, marks[i].dd);
    if (!posted || posted < cutoff) continue; // Older than window_days

    const urlM = (metaLine + body).match(/https:\/\/www\.remocate\.app\/jobs\/[A-Za-z0-9-]+/);
    if (!urlM || seenUrls.has(urlM[0])) continue;
    seenUrls.add(urlM[0]);

    let title = '', company = 'unknown';
    const tc = metaLine.match(/^\s*([^\n•]+?)\s•\s(.+)$/);
    if (tc) {
      title = clean(tc[1]);
      const cut = tc[2].search(/(Contract based|Full-time|Part-time|Internship|Freelance|Contract)\b|[\u{1F1E6}-\u{1F1FF}]{2}|📞|🌟|📍/u);
      company = clean(cut > 0 ? tc[2].slice(0, cut) : tc[2].slice(0, 40)) || 'unknown';
    }

    const headTitle = body.match(/^##+\s*(.+)$/m);
    if (headTitle) title = clean(headTitle[1]) || title;

    const countryM = metaLine.match(/[\u{1F1E6}-\u{1F1FF}]{2}\s*([^📞🏠•]+?)(?=\s*(?:📞|🌟|$))/u);
    const salaryM = metaLine.match(/\$[\d,]+(?:\s*[–-]\s*\$[\d,]+)?/g);
    const empM = metaLine.match(/(Contract based|Full-time|Part-time|Internship|Freelance|Contract)\b/);

    out.push({ json: {
      source: 'remocate', id: urlM[0], title: title || 'unknown role', company,
      url: urlM[0],
      location_raw: countryM ? countryM[1].trim() : 'Worldwide',
      work_policy: /🏠\s*Remote|\bRemote\b/i.test(metaLine) ? 'remote' : 'unknown',
      posted_date: new Date(posted).toISOString(),
      description_text: clean([
        'Title: ' + title, 'Company: ' + company,
        'Type: ' + (empM ? empM[1] : 'unknown'),
        'Salary: ' + (salaryM ? salaryM.join(' – ') : 'not listed'),
        clean(body)
      ].join('\n')).slice(0, 6000),
      visa_sponsorship: /sponsor|relocation support|visa/i.test(metaLine + body),
      heuristic_score: 0
    }});
  }
  await sleep(1500); // Politeness between category pages
}

if (out.length) return out;
if (fetchFails === CATS.length) return errItem('all category fetches failed (Jina down/rate-limited)');
if (marksFound === 0) return errItem('format changed: no date anchors found');
return [];
